WITH ranked AS (SELECT id, plan, start_date, end_date, status FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, plan ORDER BY monthly_fee DESC, id ASC) AS dedup_rank FROM subscriptions) x WHERE dedup_rank = 1) SELECT id, plan, start_date, status, CASE WHEN status RLIKE '^(EXPIRED|CANCELLED)$' THEN 'EXTENDED' WHEN status RLIKE '^(ACTIVE|PAUSED)$' THEN 'CORE' ELSE 'GROUP_B' END AS status_zone FROM ranked
